/*\n  # Fix Proposal Child Tables RLS for Consistency\n\n  ## Summary\n  Make all proposal-related tables consistent with the proposals table RLS policy.\n  If a user can view a proposal, they should be able to view (and edit if appropriate)\n  all its related data: line items, rooms, versions, etc.\n\n  ## Changes Made\n\n  1. **proposal_line_items**\n     - SELECT: Can view if user can view the parent proposal\n     - INSERT/UPDATE/DELETE: Can modify if user can view the parent proposal\n\n  2. **proposal_rooms**\n     - SELECT: Can view if user can view the parent proposal\n     - INSERT/UPDATE/DELETE: Can modify if user can view the parent proposal\n\n  3. **proposal_versions**\n     - SELECT: Can view if user can view the parent proposal\n     - INSERT: Can create if user can view the parent proposal\n\n  4. **proposal_classes**\n     - Keep existing policies (not tied to specific proposals)\n\n  ## Security Notes\n  - Maintains the proposal visibility scope system\n  - Users can only see data for proposals they have access to\n  - Consistent access control across all proposal-related tables\n*/\n\n-- =============================================\n-- PROPOSAL LINE ITEMS\n-- =============================================\n\nDROP POLICY IF EXISTS "Users can view proposal line items" ON proposal_line_items

\nDROP POLICY IF EXISTS "Users can insert proposal line items" ON proposal_line_items

\nDROP POLICY IF EXISTS "Users can update proposal line items" ON proposal_line_items

\nDROP POLICY IF EXISTS "Users can delete proposal line items" ON proposal_line_items

\n\nCREATE POLICY "Users can view proposal line items"\n  ON proposal_line_items\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_line_items.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can insert proposal line items"\n  ON proposal_line_items\n  FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_line_items.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can update proposal line items"\n  ON proposal_line_items\n  FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_line_items.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can delete proposal line items"\n  ON proposal_line_items\n  FOR DELETE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_line_items.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\n-- =============================================\n-- PROPOSAL ROOMS\n-- =============================================\n\nDROP POLICY IF EXISTS "Users can view proposal rooms" ON proposal_rooms

\nDROP POLICY IF EXISTS "Users can insert proposal rooms" ON proposal_rooms

\nDROP POLICY IF EXISTS "Users can update proposal rooms" ON proposal_rooms

\nDROP POLICY IF EXISTS "Users can delete proposal rooms" ON proposal_rooms

\n\nCREATE POLICY "Users can view proposal rooms"\n  ON proposal_rooms\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_rooms.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can insert proposal rooms"\n  ON proposal_rooms\n  FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_rooms.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can update proposal rooms"\n  ON proposal_rooms\n  FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_rooms.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can delete proposal rooms"\n  ON proposal_rooms\n  FOR DELETE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_rooms.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\n-- =============================================\n-- PROPOSAL VERSIONS\n-- =============================================\n\nDROP POLICY IF EXISTS "Authenticated users can view proposal versions" ON proposal_versions

\nDROP POLICY IF EXISTS "Authenticated users can create proposal versions" ON proposal_versions

\n\nCREATE POLICY "Users can view proposal versions"\n  ON proposal_versions\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_versions.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can create proposal versions"\n  ON proposal_versions\n  FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_versions.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n
